BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET search_path = public, extensions;
SELECT plan(10);
INSERT INTO public.tenants(id,name,slug) VALUES ('97000000-0000-0000-0000-000000000001','Pipeline test','pipeline-interview-test');
INSERT INTO auth.users(id,email) VALUES ('97000000-0000-0000-0000-000000000002','pipeline-test@example.invalid');
UPDATE public.profiles SET tenant_id='97000000-0000-0000-0000-000000000001',is_active=true WHERE id='97000000-0000-0000-0000-000000000002';
INSERT INTO public.user_roles(user_id,role) VALUES ('97000000-0000-0000-0000-000000000002','admin');
INSERT INTO public.candidates(id,first_name,last_name,tenant_id,created_by) VALUES ('97000000-0000-0000-0000-000000000003','Pipeline','Test','97000000-0000-0000-0000-000000000001','97000000-0000-0000-0000-000000000002');
INSERT INTO public.requirements(id,title,tenant_id,created_by) VALUES ('97000000-0000-0000-0000-000000000004','Pipeline test','97000000-0000-0000-0000-000000000001','97000000-0000-0000-0000-000000000002');
SET LOCAL ROLE authenticated;
SET LOCAL "request.jwt.claim.sub" = '97000000-0000-0000-0000-000000000002';
INSERT INTO public.submissions(id,candidate_id,requirement_id,stage,created_by) VALUES ('97000000-0000-0000-0000-000000000005','97000000-0000-0000-0000-000000000003','97000000-0000-0000-0000-000000000004','draft','97000000-0000-0000-0000-000000000002');
SELECT lives_ok($$UPDATE public.submissions SET stage='interview',interview_type='technical' WHERE id='97000000-0000-0000-0000-000000000005'$$,'authorized stage update saves interview type without a tailored resume');
SELECT results_eq($$SELECT interview_type FROM public.submissions WHERE id='97000000-0000-0000-0000-000000000005'$$, ARRAY['technical'::text], 'interview type persists');
SELECT throws_ok($$UPDATE public.submissions SET interview_type='invalid' WHERE id='97000000-0000-0000-0000-000000000005'$$,'23514',NULL,'invalid interview type rejected');
SELECT throws_ok($$UPDATE public.submissions SET interview_type='other',interview_other='  ' WHERE id='97000000-0000-0000-0000-000000000005'$$,'23514',NULL,'Other requires a name');
SELECT throws_ok($$UPDATE public.submissions SET interview_type='other',interview_other=repeat('x',121) WHERE id='97000000-0000-0000-0000-000000000005'$$,'23514',NULL,'Other has a database length limit');
SELECT lives_ok($$UPDATE public.submissions SET interview_type='other',interview_other=' Panel ' WHERE id='97000000-0000-0000-0000-000000000005'$$,'custom interview type saves');
SELECT results_eq($$SELECT interview_other FROM public.submissions WHERE id='97000000-0000-0000-0000-000000000005'$$,ARRAY['Panel'::text],'custom name is trimmed');
SELECT ok(EXISTS(SELECT 1 FROM public.submission_events WHERE submission_id='97000000-0000-0000-0000-000000000005' AND metadata->>'interview_other'='Panel'),'round changes are recorded in history');
UPDATE public.submissions SET stage='offer' WHERE id='97000000-0000-0000-0000-000000000005';
SELECT ok((SELECT interview_type IS NULL AND interview_other IS NULL FROM public.submissions WHERE id='97000000-0000-0000-0000-000000000005'),'leaving Interview clears current round fields');
SELECT ok(NOT has_function_privilege('authenticated','private.record_submission_interview_detail_event()','EXECUTE'),'trigger functions cannot be called by clients');
SELECT * FROM finish();
ROLLBACK;
